#!/usr/bin/env python3
"""
Applies the "Sign in with Google" (Electron desktop, Phase 1) feature to a
local checkout of g2code33/yayra. Generated from a verified-working sandbox
checkout, so every string below is byte-exact with the real source.

Run from the repository root:
    python3 apply_google_signin.py

Safe to re-run: brand-new files are skipped if they already exist, the
.gitignore line is only added once, and each BrowserShell.js edit is
skipped (not duplicated) if it was already applied by an earlier run.
electron/main.cjs and electron/preload.cjs are fully overwritten (a .bak
copy of each is made first) since they are short, simple files; review
`git diff` afterwards to confirm nothing else was lost.
"""
import os
import shutil

ROOT = os.path.dirname(os.path.abspath(__file__))

def write_new_file(relpath, content):
    path = os.path.join(ROOT, relpath)
    if os.path.exists(path):
        print(f"SKIP (already exists): {relpath}")
        return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"Created: {relpath}")

def overwrite_file(relpath, content):
    path = os.path.join(ROOT, relpath)
    if os.path.exists(path):
        shutil.copy(path, path + ".bak-before-google-signin")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"Overwrote: {relpath} (backup: {relpath}.bak-before-google-signin)")

def patch_file(relpath, edits):
    path = os.path.join(ROOT, relpath)
    if not os.path.exists(path):
        print(f"ERROR: {relpath} not found - skipping all edits for it")
        return
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()
    applied = 0
    for search, replace, label in edits:
        if replace in text:
            print(f"  - {label}: already applied, skipping")
            applied += 1
            continue
        if search not in text:
            print(f"  - {label}: COULD NOT FIND ANCHOR TEXT - apply this one manually")
            continue
        text = text.replace(search, replace, 1)
        applied += 1
        print(f"  - {label}: applied")
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)
    print(f"Applied {applied}/{len(edits)} edits successfully to {relpath}")

def ensure_gitignore_line(line):
    path = os.path.join(ROOT, ".gitignore")
    content = ""
    if os.path.exists(path):
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()
    if line in content.splitlines():
        print(f"SKIP (.gitignore already has): {line}")
        return
    with open(path, "a", encoding="utf-8") as f:
        if content and not content.endswith("\n"):
            f.write("\n")
        f.write(line + "\n")
    print(f".gitignore: added {line}")

print("=== Creating new files ===")
write_new_file('electron/authBridge.cjs', '\'use strict\';\n\n/**\n * Yayra "Sign in with Google" - main-process IPC bridge.\n *\n * Wires electron/googleAuth.cjs (the OAuth flow) and electron/authStore.cjs\n * (encrypted-at-rest session persistence) to the IPC channels the preload\n * script exposes as `window.yayra.auth` (see electron/preload.cjs). Follows\n * the same dependency-injection + factory pattern as createWebviewBridge in\n * electron/webviewBridge.cjs so it stays unit-testable without a real\n * Electron runtime, a real browser, or live network access to Google - see\n * tests/google-oauth.test.mjs and tests/electron-auth-bridge.test.mjs.\n *\n * IMPORTANT: this requires a real Google Cloud "Desktop app" OAuth Client ID\n * that only the person deploying Yayra can create (see docs/GOOGLE_SIGNIN.md\n * for the exact console steps). Without YAYRA_GOOGLE_CLIENT_ID configured,\n * sign-in fails fast with a clear \'not_configured\' error rather than silently\n * doing nothing.\n */\n\nconst AUTH_EVENT_CHANNEL = \'yayra:auth-event\';\n\nfunction createAuthBridge({\n  ipcMain,\n  shell,\n  getMainWindow,\n  authStore,\n  clientId,\n  signInImpl,\n  logger = console\n}) {\n  let signingIn = false;\n\n  function send(type, payload = {}) {\n    const win = getMainWindow?.();\n    if (!win || win.isDestroyed()) return;\n    win.webContents.send(AUTH_EVENT_CHANNEL, { type, ...payload });\n  }\n\n  async function handleSignIn() {\n    if (signingIn) return { ok: false, error: \'sign_in_already_in_progress\' };\n    if (!clientId) return { ok: false, error: \'not_configured\' };\n\n    signingIn = true;\n    send(\'signing-in\');\n    try {\n      const { profile, tokens } = await signInImpl({\n        clientId,\n        openExternal: (url) => shell.openExternal(url),\n        logger\n      });\n      authStore.save({ profile, tokens });\n      send(\'signed-in\', { profile });\n      return { ok: true, profile };\n    } catch (err) {\n      const message = err && err.message ? err.message : String(err);\n      logger?.error?.(`[yayra:auth] sign-in failed: ${message}`);\n      send(\'error\', { message });\n      return { ok: false, error: message };\n    } finally {\n      signingIn = false;\n    }\n  }\n\n  async function handleSignOut() {\n    authStore.clear();\n    send(\'signed-out\');\n    return { ok: true };\n  }\n\n  async function handleGetSession() {\n    const session = authStore.load();\n    if (!session || !session.profile) return { signedIn: false };\n    return { signedIn: true, profile: session.profile, savedAt: session.savedAt };\n  }\n\n  ipcMain.handle(\'yayra:auth-sign-in\', handleSignIn);\n  ipcMain.handle(\'yayra:auth-sign-out\', handleSignOut);\n  ipcMain.handle(\'yayra:auth-get-session\', handleGetSession);\n\n  return { handleSignIn, handleSignOut, handleGetSession };\n}\n\nmodule.exports = { createAuthBridge, AUTH_EVENT_CHANNEL };\n')
write_new_file('electron/authStore.cjs', "'use strict';\n\n/**\n * Persists the signed-in Google session for Yayra's Electron desktop build.\n *\n * Security design:\n *   - Only the non-sensitive profile (sub/email/name/picture) is ever sent\n *     to the renderer over IPC (see electron/main.cjs + preload.cjs). The\n *     renderer never sees access/refresh tokens.\n *   - The raw token response (which may include a long-lived refresh_token)\n *     is encrypted at rest with Electron's `safeStorage`, which is backed by\n *     the OS keychain (Keychain on macOS, libsecret on Linux, DPAPI on\n *     Windows) - never written to disk in plaintext.\n *   - Everything lives under Electron's per-user `userData` directory, so a\n *     signed-in session is local to one machine/profile, matching how the\n *     rest of Yayra's local-first storage works.\n *\n * Fully dependency-injected (fsImpl, safeStorageImpl, userDataDir) so this\n * is unit-testable with a real temp directory and a fake safeStorage, with\n * no real Electron runtime required.\n */\n\nconst path = require('node:path');\n\nconst FILE_NAME = 'google-session.json';\n\nfunction createAuthStore({ fs, safeStorageImpl, userDataDir }) {\n  const filePath = path.join(userDataDir, FILE_NAME);\n\n  function isEncryptionAvailable() {\n    try {\n      return Boolean(safeStorageImpl && safeStorageImpl.isEncryptionAvailable());\n    } catch {\n      return false;\n    }\n  }\n\n  function save({ profile, tokens }) {\n    const payload = { profile, savedAt: new Date().toISOString() };\n    if (isEncryptionAvailable() && tokens) {\n      const encrypted = safeStorageImpl.encryptString(JSON.stringify(tokens));\n      payload.tokensEncrypted = encrypted.toString('base64');\n    } else if (tokens) {\n      // No OS keychain available (e.g. some headless Linux CI environments).\n      // Do not persist raw tokens unencrypted; the user will simply need to\n      // sign in again next launch. The profile alone is harmless to keep.\n      payload.tokensEncrypted = null;\n      payload.encryptionUnavailable = true;\n    }\n    fs.mkdirSync(userDataDir, { recursive: true });\n    fs.writeFileSync(filePath, JSON.stringify(payload), { mode: 0o600 });\n    return payload;\n  }\n\n  function load() {\n    if (!fs.existsSync(filePath)) return null;\n    let payload;\n    try {\n      payload = JSON.parse(fs.readFileSync(filePath, 'utf8'));\n    } catch {\n      return null;\n    }\n    let tokens = null;\n    if (payload.tokensEncrypted && isEncryptionAvailable()) {\n      try {\n        const decrypted = safeStorageImpl.decryptString(Buffer.from(payload.tokensEncrypted, 'base64'));\n        tokens = JSON.parse(decrypted);\n      } catch {\n        tokens = null;\n      }\n    }\n    return { profile: payload.profile || null, tokens, savedAt: payload.savedAt || null };\n  }\n\n  function clear() {\n    try {\n      if (fs.existsSync(filePath)) fs.unlinkSync(filePath);\n    } catch {\n      // ignore - nothing to clear\n    }\n  }\n\n  return { save, load, clear };\n}\n\nmodule.exports = { createAuthStore, FILE_NAME };\n")
write_new_file('electron/googleAuth.cjs', '\'use strict\';\n\n/**\n * Yayra "Sign in with Google" - Electron desktop OAuth 2.0 client\n * ----------------------------------------------------------------\n * This is a SEPARATE concern from electron/webviewBridge.cjs\'s embedded-auth\n * handoff. That file stops Yayra from ever trying (and failing) to complete\n * a Google sign-in INSIDE the embedded browsing surface, because Google\n * actively refuses that for any embedded webview - see the comment at the\n * top of webviewBridge.cjs and\n * https://developers.google.com/identity/protocols/oauth2/policies#embedded-webviews.\n *\n * This file is how Yayra ITSELF authenticates a user against their Google\n * account for its own app-level features (not for browsing Google services\n * logged in inside the embedded view - that is never possible, by Google\'s\n * own design, from ANY embedded browser surface, and this file does not\n * attempt it). It implements the OAuth 2.0 flow Google explicitly recommends\n * for native/installed apps per RFC 8252 ("OAuth 2.0 for Native Apps"):\n *\n *   1. Open the user\'s real SYSTEM browser to Google\'s consent screen\n *      (shell.openExternal - never an embedded view).\n *   2. Use the Authorization Code + PKCE flow (no client secret - "Desktop\n *      app" OAuth clients in Google Cloud Console are public/non-confidential\n *      clients; Google explicitly does not require or expect a secret here,\n *      so it is safe for the Client ID to live in this source file).\n *   3. Catch the redirect with a short-lived local HTTP server bound to\n *      127.0.0.1 on an OS-assigned port. Google\'s own native-app guide\n *      documents this "loopback interface redirect" as the supported pattern\n *      for desktop/CLI apps; it requires no custom URI scheme registration\n *      and no domain of any kind.\n *      https://developers.google.com/identity/protocols/oauth2/native-app#loopback-ip-address\n *   4. Exchange the authorization code for tokens directly with Google\'s\n *      token endpoint, then fetch the user\'s basic profile (name/email/\n *      picture) from the userinfo endpoint.\n *\n * Every external effect (opening the browser, the HTTP server, the network\n * calls, random byte generation) is dependency-injected so PKCE/state\n * generation, callback URL parsing, and the token-exchange request shape can\n * be unit-tested without a real Electron runtime, a real browser, or a live\n * network connection to Google - see tests/google-oauth.test.mjs. The live\n * end-to-end round trip against real Google servers has NOT been run by this\n * agent (no GUI/browser or registered Client ID in this sandbox) and can\n * only be verified by a human clicking through a real consent screen with a\n * real Client ID from their own Google Cloud project.\n */\n\nconst http = require(\'node:http\');\nconst crypto = require(\'node:crypto\');\nconst { URL } = require(\'node:url\');\n\nconst GOOGLE_AUTH_ENDPOINT = \'https://accounts.google.com/o/oauth2/v2/auth\';\nconst GOOGLE_TOKEN_ENDPOINT = \'https://oauth2.googleapis.com/token\';\nconst GOOGLE_USERINFO_ENDPOINT = \'https://www.googleapis.com/oauth2/v3/userinfo\';\nconst DEFAULT_SCOPES = [\'openid\', \'email\', \'profile\'];\nconst CALLBACK_PATH = \'/callback\';\nconst DEFAULT_TIMEOUT_MS = 5 * 60 * 1000; // give the user 5 minutes to complete sign-in\n\nfunction base64url(buffer) {\n  return buffer.toString(\'base64\').replace(/\\+/g, \'-\').replace(/\\//g, \'_\').replace(/=+$/, \'\');\n}\n\n/** Generates an RFC 7636 PKCE code_verifier/code_challenge pair. */\nfunction generatePkcePair(randomBytesImpl = crypto.randomBytes) {\n  const codeVerifier = base64url(randomBytesImpl(32));\n  const codeChallenge = base64url(crypto.createHash(\'sha256\').update(codeVerifier).digest());\n  return { codeVerifier, codeChallenge };\n}\n\nfunction generateState(randomBytesImpl = crypto.randomBytes) {\n  return base64url(randomBytesImpl(16));\n}\n\nfunction buildAuthorizationUrl({ clientId, redirectUri, state, codeChallenge, scopes = DEFAULT_SCOPES }) {\n  const url = new URL(GOOGLE_AUTH_ENDPOINT);\n  url.searchParams.set(\'client_id\', clientId);\n  url.searchParams.set(\'redirect_uri\', redirectUri);\n  url.searchParams.set(\'response_type\', \'code\');\n  url.searchParams.set(\'scope\', scopes.join(\' \'));\n  url.searchParams.set(\'state\', state);\n  url.searchParams.set(\'code_challenge\', codeChallenge);\n  url.searchParams.set(\'code_challenge_method\', \'S256\');\n  url.searchParams.set(\'access_type\', \'offline\');\n  url.searchParams.set(\'prompt\', \'consent select_account\');\n  return url.toString();\n}\n\n/**\n * Parses an incoming loopback callback request\'s query string into either\n * { code, state }, { error, state }, or { ignored: true } for any request\n * that isn\'t the expected callback path (e.g. a stray favicon fetch). Pure\n * function, no I/O, fully unit-testable.\n */\nfunction parseCallbackUrl(requestUrl) {\n  const url = new URL(requestUrl, \'http://127.0.0.1\');\n  if (url.pathname !== CALLBACK_PATH) return { ignored: true };\n  const error = url.searchParams.get(\'error\');\n  const code = url.searchParams.get(\'code\');\n  const state = url.searchParams.get(\'state\');\n  if (error) return { error, state };\n  if (!code) return { error: \'missing_code\', state };\n  return { code, state };\n}\n\nconst SUCCESS_HTML = `<!doctype html><html><head><meta charset="utf-8"><title>Yayra sign-in complete</title></head>\n<body style="font-family:system-ui,sans-serif;background:#0b0d12;color:#e7e9ee;display:flex;align-items:center;justify-content:center;height:100vh;margin:0;">\n<div style="text-align:center;"><h2>Signed in to Yayra</h2><p>You can close this tab and return to the Yayra app.</p></div>\n</body></html>`;\n\nconst FAILURE_HTML = (reason) => `<!doctype html><html><head><meta charset="utf-8"><title>Yayra sign-in failed</title></head>\n<body style="font-family:system-ui,sans-serif;background:#0b0d12;color:#e7e9ee;display:flex;align-items:center;justify-content:center;height:100vh;margin:0;">\n<div style="text-align:center;"><h2>Sign-in did not complete</h2><p>${reason}</p><p>You can close this tab and return to the Yayra app.</p></div>\n</body></html>`;\n\n/**\n * Starts the one-shot loopback HTTP server, opens the user\'s system browser\n * to Google\'s consent screen once the server\'s real assigned port is known\n * (needed to build the exact redirect_uri), and resolves with the\n * authorization code once Google redirects back. Rejects on state mismatch,\n * an error param from Google (e.g. the user clicked "Cancel"), or timeout.\n */\nfunction runLoopbackAuthorization({\n  clientId,\n  scopes,\n  state,\n  codeChallenge,\n  openExternal,\n  httpModule = http,\n  timeoutMs = DEFAULT_TIMEOUT_MS,\n  logger = console,\n  onRedirectUriKnown\n}) {\n  return new Promise((resolve, reject) => {\n    let settled = false;\n    const timer = setTimeout(() => finish(new Error(\'oauth_timeout\')), timeoutMs);\n    timer.unref?.();\n\n    const server = httpModule.createServer((req, res) => {\n      const parsed = parseCallbackUrl(req.url);\n      if (parsed.ignored) {\n        res.writeHead(404).end();\n        return;\n      }\n      if (parsed.state !== state) {\n        res.writeHead(400, { \'content-type\': \'text/html\' }).end(FAILURE_HTML(\'This sign-in attempt could not be verified and was rejected for your security.\'));\n        finish(new Error(\'oauth_state_mismatch\'));\n        return;\n      }\n      if (parsed.error) {\n        const message = parsed.error === \'access_denied\' ? \'You cancelled sign-in.\' : `Google reported: ${parsed.error}`;\n        res.writeHead(200, { \'content-type\': \'text/html\' }).end(FAILURE_HTML(message));\n        finish(new Error(`oauth_error:${parsed.error}`));\n        return;\n      }\n      res.writeHead(200, { \'content-type\': \'text/html\' }).end(SUCCESS_HTML);\n      finish(null, parsed.code);\n    });\n\n    function finish(err, code) {\n      if (settled) return;\n      settled = true;\n      clearTimeout(timer);\n      server.close();\n      if (err) reject(err);\n      else resolve(code);\n    }\n\n    server.on(\'error\', finish);\n    server.listen(0, \'127.0.0.1\', async () => {\n      try {\n        const { port } = server.address();\n        const redirectUri = `http://127.0.0.1:${port}${CALLBACK_PATH}`;\n        onRedirectUriKnown?.(redirectUri);\n        const authUrl = buildAuthorizationUrl({ clientId, redirectUri, state, codeChallenge, scopes });\n        logger?.info?.(`[yayra:auth] opening system browser for Google sign-in (redirect ${redirectUri})`);\n        await openExternal(authUrl);\n      } catch (err) {\n        finish(err);\n      }\n    });\n  });\n}\n\n\nasync function exchangeCodeForTokens({ clientId, code, codeVerifier, redirectUri, fetchImpl = globalThis.fetch }) {\n  const body = new URLSearchParams({\n    client_id: clientId,\n    code,\n    code_verifier: codeVerifier,\n    grant_type: \'authorization_code\',\n    redirect_uri: redirectUri\n  });\n  const response = await fetchImpl(GOOGLE_TOKEN_ENDPOINT, {\n    method: \'POST\',\n    headers: { \'content-type\': \'application/x-www-form-urlencoded\' },\n    body: body.toString()\n  });\n  if (!response.ok) {\n    const text = await response.text().catch(() => \'\');\n    throw new Error(`token_exchange_failed:${response.status}:${text}`);\n  }\n  return response.json();\n}\n\nasync function fetchUserProfile({ accessToken, fetchImpl = globalThis.fetch }) {\n  const response = await fetchImpl(GOOGLE_USERINFO_ENDPOINT, {\n    headers: { authorization: `Bearer ${accessToken}` }\n  });\n  if (!response.ok) {\n    throw new Error(`userinfo_failed:${response.status}`);\n  }\n  const data = await response.json();\n  return {\n    sub: data.sub,\n    email: data.email || null,\n    emailVerified: Boolean(data.email_verified),\n    name: data.name || null,\n    picture: data.picture || null\n  };\n}\n\n/**\n * Runs the full interactive sign-in flow end to end: PKCE/state generation,\n * loopback server + system browser handoff, code-for-token exchange, and\n * profile fetch. Returns { profile, tokens } on success, where tokens is the\n * raw Google token response ({ access_token, refresh_token?, expires_in,\n * id_token, ... }). Throws on cancellation, state mismatch, timeout, or any\n * network/HTTP failure - callers should surface a user-facing message rather\n * than assuming success.\n */\nasync function signInWithGoogle({\n  clientId,\n  scopes = DEFAULT_SCOPES,\n  openExternal,\n  httpModule = http,\n  fetchImpl = globalThis.fetch,\n  randomBytesImpl = crypto.randomBytes,\n  timeoutMs = DEFAULT_TIMEOUT_MS,\n  logger = console\n}) {\n  if (!clientId) throw new Error(\'google_oauth_not_configured\');\n  if (typeof openExternal !== \'function\') throw new Error(\'openExternal_required\');\n\n  const { codeVerifier, codeChallenge } = generatePkcePair(randomBytesImpl);\n  const state = generateState(randomBytesImpl);\n\n  let capturedRedirectUri = null;\n  const code = await runLoopbackAuthorization({\n    clientId,\n    scopes,\n    state,\n    codeChallenge,\n    openExternal,\n    httpModule,\n    timeoutMs,\n    logger,\n    onRedirectUriKnown: (uri) => { capturedRedirectUri = uri; }\n  });\n\n  const tokens = await exchangeCodeForTokens({ clientId, code, codeVerifier, redirectUri: capturedRedirectUri, fetchImpl });\n  const profile = await fetchUserProfile({ accessToken: tokens.access_token, fetchImpl });\n\n  return { profile, tokens };\n}\n\nmodule.exports = {\n  DEFAULT_SCOPES,\n  CALLBACK_PATH,\n  GOOGLE_AUTH_ENDPOINT,\n  GOOGLE_TOKEN_ENDPOINT,\n  GOOGLE_USERINFO_ENDPOINT,\n  generatePkcePair,\n  generateState,\n  buildAuthorizationUrl,\n  parseCallbackUrl,\n  runLoopbackAuthorization,\n  exchangeCodeForTokens,\n  fetchUserProfile,\n  signInWithGoogle\n};\n')
write_new_file('electron/googleAuthConfig.cjs', '\'use strict\';\n\n/**\n * Resolves the Google OAuth "Desktop app" Client ID for Sign in with Google.\n *\n * A Desktop-app Client ID is NOT a secret (Google\'s own docs describe these\n * as public/non-confidential clients - see\n * https://developers.google.com/identity/protocols/oauth2/native-app), so it\n * is fine for it to end up in a built app. It is still kept out of this\n * repository\'s tracked source because it is specific to whoever deploys\n * their own instance of Yayra - see docs/GOOGLE_SIGNIN.md for how to create\n * one and where to put it. Resolution order:\n *   1. YAYRA_GOOGLE_CLIENT_ID environment variable (handy for local dev).\n *   2. electron/google-auth.config.json next to this file, shape\n *      { "clientId": "....apps.googleusercontent.com" } - gitignored, and\n *      packaged into the app by electron-builder\'s "electron/**" files glob\n *      so it travels with a built installer if present at build time.\n * Returns null (not a throw) when neither is configured, so callers can\n * surface a clear "not configured" state instead of crashing.\n */\n\nconst path = require(\'node:path\');\n\nfunction readConfigFile(fs, configPath) {\n  try {\n    if (!fs.existsSync(configPath)) return null;\n    const raw = JSON.parse(fs.readFileSync(configPath, \'utf8\'));\n    return typeof raw.clientId === \'string\' && raw.clientId.trim() ? raw.clientId.trim() : null;\n  } catch {\n    return null;\n  }\n}\n\nfunction resolveGoogleClientId({ env = process.env, fs = require(\'node:fs\'), configDir = __dirname } = {}) {\n  const fromEnv = env.YAYRA_GOOGLE_CLIENT_ID && env.YAYRA_GOOGLE_CLIENT_ID.trim();\n  if (fromEnv) return fromEnv;\n  return readConfigFile(fs, path.join(configDir, \'google-auth.config.json\'));\n}\n\nmodule.exports = { resolveGoogleClientId };\n')
write_new_file('docs/GOOGLE_SIGNIN.md', '# Sign in with Google (Electron desktop) — setup & architecture\n\n## What this is, and what it is not\n\nThis feature gives **Yayra itself** a real, app-level Google identity (name,\nemail, profile picture), so Yayra\'s own UI can show "Signed in as ..." /\n"Sign out". It is **not** a way to use Gmail, Drive, or any other Google\nservice logged-in *inside* Yayra\'s embedded browsing view — Google actively\ndetects and blocks sign-in inside any embedded browser surface (WebView,\nWebContentsView, iframe, etc.) as an anti-phishing measure. See\n[Google\'s own policy](https://developers.google.com/identity/protocols/oauth2/policies#embedded-webviews).\nYayra does not attempt to bypass that; `electron/webviewBridge.cjs` already\nhands those navigations off to the user\'s real system browser.\n\nThis document covers **Phase 1: Electron desktop only**. Web/PWA and\nAndroid/iOS are separate follow-up work (see "Status by platform" below).\n\n## How it works\n\nYayra uses the OAuth 2.0 flow Google explicitly recommends for native/desktop\napps (RFC 8252, "OAuth 2.0 for Native Apps"):\n\n1. Yayra opens your **real system browser** (never an embedded view) to\n   Google\'s consent screen.\n2. It uses **Authorization Code + PKCE** — there is no client secret, because\n   a "Desktop app" OAuth client in Google Cloud Console is a public,\n   non-confidential client by design.\n3. A short-lived local HTTP server on `127.0.0.1` (an OS-assigned free port,\n   picked fresh every sign-in) catches Google\'s redirect. This is Google\'s\n   own documented ["loopback interface redirect"](https://developers.google.com/identity/protocols/oauth2/native-app#loopback-ip-address)\n   pattern — **no domain, no custom URL scheme, and no fixed port need to be\n   registered.**\n4. Yayra exchanges the authorization code for tokens directly with Google,\n   then fetches your basic profile (name/email/picture).\n5. The profile (not the tokens) is shown in Yayra\'s UI. The raw tokens are\n   encrypted at rest using Electron\'s `safeStorage` (backed by your OS\n   keychain — Keychain on macOS, libsecret on Linux, DPAPI on Windows) and\n   are never sent to the renderer/web UI process.\n\nRelevant source files:\n- `electron/googleAuth.cjs` — the OAuth flow itself (PKCE, loopback server,\n  token exchange, userinfo fetch). Fully unit-tested in\n  `tests/google-oauth.test.mjs` with a real local socket and a fake Google\n  (no live network access).\n- `electron/authStore.cjs` — encrypted-at-rest session persistence. Tested in\n  `tests/google-auth-store.test.mjs`.\n- `electron/authBridge.cjs` — wires the above to IPC channels\n  (`yayra:auth-sign-in`, `yayra:auth-sign-out`, `yayra:auth-get-session`).\n  Tested in `tests/google-auth-bridge.test.mjs`.\n- `electron/googleAuthConfig.cjs` — resolves your Client ID. Tested in\n  `tests/google-auth-config.test.mjs`.\n- `electron/preload.cjs` — exposes `window.yayra.auth.{signIn, signOut,\n  getSession, onEvent}` to the renderer.\n- `packages/shared-ui/src/components/BrowserShell.js` — the "Account"\n  section inside Settings (`yayra://settings`) that calls the above.\n\n## Creating your own Google Cloud OAuth Client ID\n\nYou (not this agent) need to create this, because it ties to a Google Cloud\nproject you own. **No domain purchase is required.**\n\n1. Go to the [Google Cloud Console](https://console.cloud.google.com/) and\n   create (or select) a project.\n2. Go to **APIs & Services → OAuth consent screen**. Choose "External" (or\n   "Internal" if you have a Google Workspace), fill in the app name/logo/\n   support email, and add the `openid`, `email`, and `profile` scopes (these\n   are the only ones Yayra requests). While the app is in "Testing" mode you\n   can add your own Google account as a test user; "Publish" it later if you\n   want any Google account to be able to sign in.\n3. Go to **APIs & Services → Credentials → Create Credentials → OAuth client\n   ID**.\n4. For **Application type, choose "Desktop app"**. Give it any name (e.g.\n   "Yayra Desktop"). Click Create.\n5. Copy the generated **Client ID** (it looks like\n   `123456789-abc...apps.googleusercontent.com`). You do **not** need the\n   client secret Google also shows you — Desktop app clients use PKCE and\n   never send a secret; `electron/googleAuth.cjs` never reads or stores one.\n6. No redirect URI needs to be registered for "Desktop app" clients using the\n   loopback pattern — Google allows any `http://127.0.0.1:<port>/...` or\n   `http://localhost:<port>/...` redirect automatically for this client type.\n\n## Configuring Yayra with your Client ID\n\nPick one:\n\n- **Local development:** export an environment variable before launching\n  Electron:\n  ```bash\n  export YAYRA_GOOGLE_CLIENT_ID="123456789-abc...apps.googleusercontent.com"\n  ```\n- **Packaged builds:** create `electron/google-auth.config.json` (already\n  gitignored — it will never be committed) before running\n  `npm run package:linux` / `package:win` / etc.:\n  ```json\n  { "clientId": "123456789-abc...apps.googleusercontent.com" }\n  ```\n  This file is included by electron-builder\'s existing `electron/**/*` files\n  glob, so it travels with the built installer.\n\nIf neither is set, the "Sign in with Google" button in Settings → Account\nwill show a clear "not configured" error instead of silently failing.\n\n## Status by platform\n\n| Platform | Status |\n| --- | --- |\n| Electron desktop (Linux/Windows) | **Implemented** in this change; the live round trip against real Google servers has **not** been run by this agent (no GUI browser or registered Client ID in this sandbox) and must be verified by you on your own machine with your own Client ID. |\n| Web / PWA (`yayra.pages.dev`) | **Not yet implemented.** Would use the same Authorization Code + PKCE flow with a popup/redirect to `https://yayra.pages.dev/auth/callback` instead of a loopback server — separate follow-up work. |\n| Android / iOS (Capacitor) | **Not yet implemented, deferred.** Needs a dedicated Capacitor OAuth plugin (not currently a project dependency) and real-device/emulator testing this sandbox cannot perform. |\n\n## How to verify it actually works (you must do this)\n\n1. Create your Client ID per the steps above and set it via the environment\n   variable (fastest for a first test).\n2. Run the desktop app (`npm run build:web && npx electron .` or your usual\n   dev launch command) on a machine with a real display.\n3. Open Settings → Account → "Sign in with Google".\n4. Your default system browser should open to Google\'s consent screen. Sign\n   in and approve.\n5. Your browser tab should show "Signed in to Yayra — you can close this tab"\n   and Yayra\'s Settings → Account should now show your name/email.\n6. Confirm "Sign out" clears it, and relaunching Yayra without signing in\n   again still remembers you were signed in (session persistence) until you\n   explicitly sign out.\n')
write_new_file('tests/google-oauth.test.mjs', 'import test from \'node:test\';\nimport assert from \'node:assert/strict\';\nimport http from \'node:http\';\nimport {\n  generatePkcePair,\n  generateState,\n  buildAuthorizationUrl,\n  parseCallbackUrl,\n  exchangeCodeForTokens,\n  fetchUserProfile,\n  signInWithGoogle,\n  CALLBACK_PATH,\n  DEFAULT_SCOPES\n} from \'../electron/googleAuth.cjs\';\n\n// --- PKCE / state generation --------------------------------------------\n\ntest(\'generatePkcePair: produces a base64url verifier and its S256 challenge, no padding/unsafe chars\', () => {\n  const { codeVerifier, codeChallenge } = generatePkcePair();\n  assert.match(codeVerifier, /^[A-Za-z0-9_-]+$/);\n  assert.match(codeChallenge, /^[A-Za-z0-9_-]+$/);\n  assert.ok(codeVerifier.length >= 43); // RFC 7636 minimum entropy\n  assert.notEqual(codeVerifier, codeChallenge);\n});\n\ntest(\'generatePkcePair: is deterministic given injected randomBytes, so the challenge is a pure function of the verifier\', () => {\n  const fixedRandom = () => Buffer.alloc(32, 7);\n  const a = generatePkcePair(fixedRandom);\n  const b = generatePkcePair(fixedRandom);\n  assert.equal(a.codeVerifier, b.codeVerifier);\n  assert.equal(a.codeChallenge, b.codeChallenge);\n});\n\ntest(\'generateState: produces different values on each call with real randomness\', () => {\n  const s1 = generateState();\n  const s2 = generateState();\n  assert.notEqual(s1, s2);\n  assert.match(s1, /^[A-Za-z0-9_-]+$/);\n});\n\n// --- Authorization URL ----------------------------------------------------\n\ntest(\'buildAuthorizationUrl: includes PKCE S256 challenge, state, and default identity-only scopes\', () => {\n  const url = new URL(buildAuthorizationUrl({\n    clientId: \'client-123.apps.googleusercontent.com\',\n    redirectUri: \'http://127.0.0.1:54321/callback\',\n    state: \'abc\',\n    codeChallenge: \'xyz\'\n  }));\n  assert.equal(url.hostname, \'accounts.google.com\');\n  assert.equal(url.searchParams.get(\'client_id\'), \'client-123.apps.googleusercontent.com\');\n  assert.equal(url.searchParams.get(\'redirect_uri\'), \'http://127.0.0.1:54321/callback\');\n  assert.equal(url.searchParams.get(\'response_type\'), \'code\');\n  assert.equal(url.searchParams.get(\'code_challenge\'), \'xyz\');\n  assert.equal(url.searchParams.get(\'code_challenge_method\'), \'S256\');\n  assert.equal(url.searchParams.get(\'state\'), \'abc\');\n  assert.equal(url.searchParams.get(\'scope\'), DEFAULT_SCOPES.join(\' \'));\n  // Must never request broad Gmail/Drive/etc access for simple app sign-in.\n  assert.ok(!url.searchParams.get(\'scope\').includes(\'gmail\'));\n});\n\ntest(\'buildAuthorizationUrl: honors custom scopes when provided\', () => {\n  const url = new URL(buildAuthorizationUrl({\n    clientId: \'c\',\n    redirectUri: \'http://127.0.0.1:1/callback\',\n    state: \'s\',\n    codeChallenge: \'ch\',\n    scopes: [\'openid\', \'email\']\n  }));\n  assert.equal(url.searchParams.get(\'scope\'), \'openid email\');\n});\n\n// --- Callback URL parsing --------------------------------------------------\n\ntest(\'parseCallbackUrl: extracts code and state from a successful redirect\', () => {\n  const result = parseCallbackUrl(`${CALLBACK_PATH}?code=abc123&state=xyz789`);\n  assert.deepEqual(result, { code: \'abc123\', state: \'xyz789\' });\n});\n\ntest(\'parseCallbackUrl: surfaces the error param when the user cancels/denies consent\', () => {\n  const result = parseCallbackUrl(`${CALLBACK_PATH}?error=access_denied&state=xyz789`);\n  assert.deepEqual(result, { error: \'access_denied\', state: \'xyz789\' });\n});\n\ntest(\'parseCallbackUrl: treats a missing code with no error as a malformed callback\', () => {\n  const result = parseCallbackUrl(`${CALLBACK_PATH}?state=xyz789`);\n  assert.equal(result.error, \'missing_code\');\n});\n\ntest(\'parseCallbackUrl: ignores requests to any path other than the OAuth callback\', () => {\n  assert.deepEqual(parseCallbackUrl(\'/favicon.ico\'), { ignored: true });\n  assert.deepEqual(parseCallbackUrl(\'/\'), { ignored: true });\n});\n\n// --- Token exchange / userinfo (fetch injected, no real network) ---------\n\ntest(\'exchangeCodeForTokens: POSTs the correct PKCE token-exchange body with no client_secret\', async () => {\n  let captured = null;\n  const fakeFetch = async (url, options) => {\n    captured = { url, options };\n    return { ok: true, json: async () => ({ access_token: \'at\', refresh_token: \'rt\', expires_in: 3600, id_token: \'idt\' }) };\n  };\n  const tokens = await exchangeCodeForTokens({\n    clientId: \'client-123\',\n    code: \'auth-code\',\n    codeVerifier: \'verifier-abc\',\n    redirectUri: \'http://127.0.0.1:9999/callback\',\n    fetchImpl: fakeFetch\n  });\n  assert.equal(captured.url, \'https://oauth2.googleapis.com/token\');\n  assert.equal(captured.options.method, \'POST\');\n  const body = new URLSearchParams(captured.options.body);\n  assert.equal(body.get(\'client_id\'), \'client-123\');\n  assert.equal(body.get(\'code\'), \'auth-code\');\n  assert.equal(body.get(\'code_verifier\'), \'verifier-abc\');\n  assert.equal(body.get(\'grant_type\'), \'authorization_code\');\n  assert.equal(body.get(\'redirect_uri\'), \'http://127.0.0.1:9999/callback\');\n  assert.equal(body.has(\'client_secret\'), false); // public/PKCE client: never send a secret\n  assert.deepEqual(tokens, { access_token: \'at\', refresh_token: \'rt\', expires_in: 3600, id_token: \'idt\' });\n});\n\ntest(\'exchangeCodeForTokens: throws a descriptive error on a non-OK response instead of returning partial data\', async () => {\n  const fakeFetch = async () => ({ ok: false, status: 400, text: async () => \'{"error":"invalid_grant"}\' });\n  await assert.rejects(\n    () => exchangeCodeForTokens({ clientId: \'c\', code: \'x\', codeVerifier: \'v\', redirectUri: \'r\', fetchImpl: fakeFetch }),\n    /token_exchange_failed:400/\n  );\n});\n\ntest(\'fetchUserProfile: sends the bearer token and normalizes the response shape\', async () => {\n  let capturedHeaders = null;\n  const fakeFetch = async (url, options) => {\n    capturedHeaders = options.headers;\n    return {\n      ok: true,\n      json: async () => ({ sub: \'12345\', email: \'user@example.com\', email_verified: true, name: \'Ama Mensah\', picture: \'https://example.com/p.jpg\' })\n    };\n  };\n  const profile = await fetchUserProfile({ accessToken: \'tok-abc\', fetchImpl: fakeFetch });\n  assert.equal(capturedHeaders.authorization, \'Bearer tok-abc\');\n  assert.deepEqual(profile, {\n    sub: \'12345\',\n    email: \'user@example.com\',\n    emailVerified: true,\n    name: \'Ama Mensah\',\n    picture: \'https://example.com/p.jpg\'\n  });\n});\n\ntest(\'fetchUserProfile: throws on a non-OK response\', async () => {\n  const fakeFetch = async () => ({ ok: false, status: 401 });\n  await assert.rejects(() => fetchUserProfile({ accessToken: \'bad\', fetchImpl: fakeFetch }), /userinfo_failed:401/);\n});\n\n// --- Full signInWithGoogle flow (real loopback socket, fake browser+fetch) -\n\nfunction openExternalThatHitsCallback(query) {\n  // Simulates the user completing consent in their real system browser by\n  // issuing the exact redirect request Google would send, against whatever\n  // ephemeral port the loopback server actually bound to.\n  return async (authUrl) => {\n    const url = new URL(authUrl);\n    const redirectUri = new URL(url.searchParams.get(\'redirect_uri\'));\n    const callback = new URL(redirectUri.toString());\n    Object.entries(query(url)).forEach(([k, v]) => callback.searchParams.set(k, v));\n    await new Promise((resolve, reject) => {\n      http.get(callback, (res) => {\n        res.resume();\n        res.on(\'end\', resolve);\n      }).on(\'error\', reject);\n    });\n  };\n}\n\ntest(\'signInWithGoogle: completes the full PKCE + loopback + token + profile flow\', async () => {\n  const fakeFetch = async (url, options) => {\n    if (url === \'https://oauth2.googleapis.com/token\') {\n      const body = new URLSearchParams(options.body);\n      assert.equal(body.get(\'client_id\'), \'real-client-id\');\n      return { ok: true, json: async () => ({ access_token: \'access-xyz\', refresh_token: \'refresh-xyz\', expires_in: 3600 }) };\n    }\n    if (url === \'https://www.googleapis.com/oauth2/v3/userinfo\') {\n      assert.equal(options.headers.authorization, \'Bearer access-xyz\');\n      return { ok: true, json: async () => ({ sub: \'1\', email: \'a@b.com\', name: \'A B\' }) };\n    }\n    throw new Error(`unexpected fetch url: ${url}`);\n  };\n\n  const openExternal = openExternalThatHitsCallback((url) => ({ code: \'auth-code-123\', state: url.searchParams.get(\'state\') }));\n\n  const result = await signInWithGoogle({\n    clientId: \'real-client-id\',\n    openExternal,\n    fetchImpl: fakeFetch,\n    timeoutMs: 5000\n  });\n\n  assert.equal(result.profile.email, \'a@b.com\');\n  assert.equal(result.tokens.access_token, \'access-xyz\');\n});\n\ntest(\'signInWithGoogle: rejects when the callback state does not match (CSRF protection)\', async () => {\n  const openExternal = openExternalThatHitsCallback(() => ({ code: \'c\', state: \'wrong-state\' }));\n  await assert.rejects(\n    () => signInWithGoogle({ clientId: \'c\', openExternal, fetchImpl: async () => { throw new Error(\'should not be called\'); }, timeoutMs: 5000 }),\n    /oauth_state_mismatch/\n  );\n});\n\ntest(\'signInWithGoogle: rejects cleanly when the user cancels consent (access_denied)\', async () => {\n  const openExternal = openExternalThatHitsCallback((url) => ({ error: \'access_denied\', state: url.searchParams.get(\'state\') }));\n  await assert.rejects(\n    () => signInWithGoogle({ clientId: \'c\', openExternal, fetchImpl: async () => { throw new Error(\'should not be called\'); }, timeoutMs: 5000 }),\n    /oauth_error:access_denied/\n  );\n});\n\ntest(\'signInWithGoogle: rejects fast with a clear error when no Client ID is configured\', async () => {\n  await assert.rejects(\n    () => signInWithGoogle({ clientId: \'\', openExternal: async () => {}, fetchImpl: async () => { throw new Error(\'should not be called\'); } }),\n    /google_oauth_not_configured/\n  );\n});\n\ntest(\'signInWithGoogle: rejects on timeout if the browser never completes the redirect\', async () => {\n  const openExternal = async () => {\n    // Simulate a user who never finishes signing in: never hits the\n    // callback server at all.\n  };\n  await assert.rejects(\n    () => signInWithGoogle({ clientId: \'c\', openExternal, fetchImpl: async () => { throw new Error(\'should not be called\'); }, timeoutMs: 50 }),\n    /oauth_timeout/\n  );\n});\n\ntest(\'signInWithGoogle: propagates a failed token exchange instead of reporting success\', async () => {\n  const openExternal = openExternalThatHitsCallback((url) => ({ code: \'c\', state: url.searchParams.get(\'state\') }));\n  const fakeFetch = async () => ({ ok: false, status: 400, text: async () => \'bad request\' });\n  await assert.rejects(\n    () => signInWithGoogle({ clientId: \'c\', openExternal, fetchImpl: fakeFetch, timeoutMs: 5000 }),\n    /token_exchange_failed/\n  );\n});\n')
write_new_file('tests/google-auth-store.test.mjs', 'import test from \'node:test\';\nimport assert from \'node:assert/strict\';\nimport fs from \'node:fs\';\nimport os from \'node:os\';\nimport path from \'node:path\';\nimport { createAuthStore } from \'../electron/authStore.cjs\';\n\nfunction makeTempDir() {\n  return fs.mkdtempSync(path.join(os.tmpdir(), \'yayra-auth-store-\'));\n}\n\nfunction fakeSafeStorage(available = true) {\n  return {\n    isEncryptionAvailable: () => available,\n    // Trivial reversible "encryption" stand-in for an OS keychain - good\n    // enough to prove the store round-trips through it correctly.\n    encryptString: (str) => Buffer.from(`enc:${str}`, \'utf8\'),\n    decryptString: (buf) => buf.toString(\'utf8\').replace(/^enc:/, \'\')\n  };\n}\n\ntest(\'authStore: save() then load() round-trips profile and tokens when encryption is available\', () => {\n  const dir = makeTempDir();\n  const store = createAuthStore({ fs, safeStorageImpl: fakeSafeStorage(true), userDataDir: dir });\n\n  store.save({ profile: { sub: \'1\', email: \'a@b.com\' }, tokens: { access_token: \'at\', refresh_token: \'rt\' } });\n  const loaded = store.load();\n\n  assert.deepEqual(loaded.profile, { sub: \'1\', email: \'a@b.com\' });\n  assert.deepEqual(loaded.tokens, { access_token: \'at\', refresh_token: \'rt\' });\n  assert.ok(loaded.savedAt);\n});\n\ntest(\'authStore: tokens are never written to disk in plaintext\', () => {\n  const dir = makeTempDir();\n  const store = createAuthStore({ fs, safeStorageImpl: fakeSafeStorage(true), userDataDir: dir });\n  store.save({ profile: { sub: \'1\' }, tokens: { access_token: \'super-secret-access-token\', refresh_token: \'super-secret-refresh-token\' } });\n\n  const raw = fs.readFileSync(path.join(dir, \'google-session.json\'), \'utf8\');\n  assert.ok(!raw.includes(\'super-secret-access-token\'));\n  assert.ok(!raw.includes(\'super-secret-refresh-token\'));\n});\n\ntest(\'authStore: load() returns null when nothing has been saved\', () => {\n  const dir = makeTempDir();\n  const store = createAuthStore({ fs, safeStorageImpl: fakeSafeStorage(true), userDataDir: dir });\n  assert.equal(store.load(), null);\n});\n\ntest(\'authStore: clear() removes the session so a subsequent load() returns null\', () => {\n  const dir = makeTempDir();\n  const store = createAuthStore({ fs, safeStorageImpl: fakeSafeStorage(true), userDataDir: dir });\n  store.save({ profile: { sub: \'1\' }, tokens: { access_token: \'at\' } });\n  assert.ok(store.load());\n  store.clear();\n  assert.equal(store.load(), null);\n});\n\ntest(\'authStore: clear() on an already-empty store does not throw\', () => {\n  const dir = makeTempDir();\n  const store = createAuthStore({ fs, safeStorageImpl: fakeSafeStorage(true), userDataDir: dir });\n  assert.doesNotThrow(() => store.clear());\n});\n\ntest(\'authStore: when OS keychain encryption is unavailable, profile is still kept but tokens are not persisted unencrypted\', () => {\n  const dir = makeTempDir();\n  const store = createAuthStore({ fs, safeStorageImpl: fakeSafeStorage(false), userDataDir: dir });\n  store.save({ profile: { sub: \'1\', email: \'a@b.com\' }, tokens: { access_token: \'secret\' } });\n\n  const raw = fs.readFileSync(path.join(dir, \'google-session.json\'), \'utf8\');\n  assert.ok(!raw.includes(\'secret\'));\n\n  const loaded = store.load();\n  assert.deepEqual(loaded.profile, { sub: \'1\', email: \'a@b.com\' });\n  assert.equal(loaded.tokens, null);\n});\n\ntest(\'authStore: load() tolerates a corrupted session file instead of throwing\', () => {\n  const dir = makeTempDir();\n  fs.mkdirSync(dir, { recursive: true });\n  fs.writeFileSync(path.join(dir, \'google-session.json\'), \'not valid json {{{\');\n  const store = createAuthStore({ fs, safeStorageImpl: fakeSafeStorage(true), userDataDir: dir });\n  assert.equal(store.load(), null);\n});\n')
write_new_file('tests/google-auth-bridge.test.mjs', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { createAuthBridge, AUTH_EVENT_CHANNEL } from '../electron/authBridge.cjs';\n\nfunction fakeIpcMain() {\n  const handlers = new Map();\n  return {\n    handle: (channel, fn) => handlers.set(channel, fn),\n    invoke: (channel, ...args) => handlers.get(channel)(...args)\n  };\n}\n\nfunction fakeWindow() {\n  const sent = [];\n  return {\n    isDestroyed: () => false,\n    webContents: { send: (channel, payload) => sent.push({ channel, payload }) },\n    sent\n  };\n}\n\nfunction fakeAuthStore() {\n  let session = null;\n  return {\n    save: ({ profile, tokens }) => { session = { profile, tokens }; },\n    load: () => (session ? { profile: session.profile, savedAt: '2026-01-01T00:00:00.000Z' } : null),\n    clear: () => { session = null; }\n  };\n}\n\ntest('authBridge: sign-in success persists the session and emits signed-in with only the profile (no tokens over IPC)', async () => {\n  const ipcMain = fakeIpcMain();\n  const win = fakeWindow();\n  const authStore = fakeAuthStore();\n  const shell = { openExternal: async () => {} };\n  const signInImpl = async () => ({ profile: { sub: '1', email: 'a@b.com' }, tokens: { access_token: 'secret-at', refresh_token: 'secret-rt' } });\n\n  createAuthBridge({ ipcMain, shell, getMainWindow: () => win, authStore, clientId: 'client-123', signInImpl });\n\n  const result = await ipcMain.invoke('yayra:auth-sign-in');\n  assert.deepEqual(result, { ok: true, profile: { sub: '1', email: 'a@b.com' } });\n\n  const events = win.sent.filter((e) => e.channel === AUTH_EVENT_CHANNEL).map((e) => e.payload.type);\n  assert.deepEqual(events, ['signing-in', 'signed-in']);\n\n  // Never leak tokens to the renderer under any event.\n  const anyTokenLeak = win.sent.some((e) => JSON.stringify(e.payload).includes('secret-'));\n  assert.equal(anyTokenLeak, false);\n\n  const session = await ipcMain.invoke('yayra:auth-get-session');\n  assert.deepEqual(session, { signedIn: true, profile: { sub: '1', email: 'a@b.com' }, savedAt: '2026-01-01T00:00:00.000Z' });\n});\n\ntest('authBridge: sign-in failure emits an error event and does not persist a session', async () => {\n  const ipcMain = fakeIpcMain();\n  const win = fakeWindow();\n  const authStore = fakeAuthStore();\n  const shell = { openExternal: async () => {} };\n  const signInImpl = async () => { throw new Error('oauth_error:access_denied'); };\n\n  createAuthBridge({ ipcMain, shell, getMainWindow: () => win, authStore, clientId: 'client-123', signInImpl });\n\n  const result = await ipcMain.invoke('yayra:auth-sign-in');\n  assert.equal(result.ok, false);\n  assert.match(result.error, /access_denied/);\n\n  const events = win.sent.filter((e) => e.channel === AUTH_EVENT_CHANNEL).map((e) => e.payload.type);\n  assert.deepEqual(events, ['signing-in', 'error']);\n\n  const session = await ipcMain.invoke('yayra:auth-get-session');\n  assert.deepEqual(session, { signedIn: false });\n});\n\ntest('authBridge: sign-in fails fast with not_configured when no Client ID is set, without ever opening a browser', async () => {\n  const ipcMain = fakeIpcMain();\n  const win = fakeWindow();\n  const authStore = fakeAuthStore();\n  let openedUrl = null;\n  const shell = { openExternal: async (url) => { openedUrl = url; } };\n  const signInImpl = async () => { throw new Error('should never be called'); };\n\n  createAuthBridge({ ipcMain, shell, getMainWindow: () => win, authStore, clientId: null, signInImpl });\n\n  const result = await ipcMain.invoke('yayra:auth-sign-in');\n  assert.deepEqual(result, { ok: false, error: 'not_configured' });\n  assert.equal(openedUrl, null);\n});\n\ntest('authBridge: a second concurrent sign-in call is rejected while one is already in progress', async () => {\n  const ipcMain = fakeIpcMain();\n  const win = fakeWindow();\n  const authStore = fakeAuthStore();\n  const shell = { openExternal: async () => {} };\n  let resolveFirst;\n  const signInImpl = async () => new Promise((resolve) => { resolveFirst = resolve; });\n\n  createAuthBridge({ ipcMain, shell, getMainWindow: () => win, authStore, clientId: 'c', signInImpl });\n\n  const firstCallPromise = ipcMain.invoke('yayra:auth-sign-in');\n  const secondResult = await ipcMain.invoke('yayra:auth-sign-in');\n  assert.deepEqual(secondResult, { ok: false, error: 'sign_in_already_in_progress' });\n\n  resolveFirst({ profile: { sub: '1' }, tokens: {} });\n  const firstResult = await firstCallPromise;\n  assert.equal(firstResult.ok, true);\n});\n\ntest('authBridge: sign-out clears the stored session and emits signed-out', async () => {\n  const ipcMain = fakeIpcMain();\n  const win = fakeWindow();\n  const authStore = fakeAuthStore();\n  authStore.save({ profile: { sub: '1' }, tokens: { access_token: 'x' } });\n  const shell = { openExternal: async () => {} };\n\n  createAuthBridge({ ipcMain, shell, getMainWindow: () => win, authStore, clientId: 'c', signInImpl: async () => ({}) });\n\n  const result = await ipcMain.invoke('yayra:auth-sign-out');\n  assert.deepEqual(result, { ok: true });\n  assert.deepEqual(await ipcMain.invoke('yayra:auth-get-session'), { signedIn: false });\n\n  const events = win.sent.filter((e) => e.channel === AUTH_EVENT_CHANNEL).map((e) => e.payload.type);\n  assert.deepEqual(events, ['signed-out']);\n});\n\ntest('authBridge: get-session reflects no prior session as signedIn: false', async () => {\n  const ipcMain = fakeIpcMain();\n  const win = fakeWindow();\n  const authStore = fakeAuthStore();\n  createAuthBridge({ ipcMain, shell: { openExternal: async () => {} }, getMainWindow: () => win, authStore, clientId: 'c', signInImpl: async () => ({}) });\n\n  assert.deepEqual(await ipcMain.invoke('yayra:auth-get-session'), { signedIn: false });\n});\n")
write_new_file('tests/google-auth-config.test.mjs', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { resolveGoogleClientId } from '../electron/googleAuthConfig.cjs';\n\nfunction fakeFs(files = {}) {\n  return {\n    existsSync: (p) => Object.prototype.hasOwnProperty.call(files, p),\n    readFileSync: (p) => files[p]\n  };\n}\n\ntest('resolveGoogleClientId: prefers the YAYRA_GOOGLE_CLIENT_ID environment variable', () => {\n  const id = resolveGoogleClientId({\n    env: { YAYRA_GOOGLE_CLIENT_ID: '  env-client-id  ' },\n    fs: fakeFs(),\n    configDir: '/app/electron'\n  });\n  assert.equal(id, 'env-client-id');\n});\n\ntest('resolveGoogleClientId: falls back to electron/google-auth.config.json when env is unset', () => {\n  const id = resolveGoogleClientId({\n    env: {},\n    fs: fakeFs({ '/app/electron/google-auth.config.json': JSON.stringify({ clientId: 'file-client-id' }) }),\n    configDir: '/app/electron'\n  });\n  assert.equal(id, 'file-client-id');\n});\n\ntest('resolveGoogleClientId: returns null (not a throw) when neither source is configured', () => {\n  const id = resolveGoogleClientId({ env: {}, fs: fakeFs(), configDir: '/app/electron' });\n  assert.equal(id, null);\n});\n\ntest('resolveGoogleClientId: returns null for a malformed config file instead of throwing', () => {\n  const id = resolveGoogleClientId({\n    env: {},\n    fs: fakeFs({ '/app/electron/google-auth.config.json': 'not valid json' }),\n    configDir: '/app/electron'\n  });\n  assert.equal(id, null);\n});\n\ntest('resolveGoogleClientId: returns null when the config file has no clientId field', () => {\n  const id = resolveGoogleClientId({\n    env: {},\n    fs: fakeFs({ '/app/electron/google-auth.config.json': JSON.stringify({ foo: 'bar' }) }),\n    configDir: '/app/electron'\n  });\n  assert.equal(id, null);\n});\n")

