overwrite_file('electron/main.cjs', 'const { app, BrowserWindow, WebContentsView, ipcMain, protocol, net, shell, safeStorage } = require(\'electron\');\nconst path = require(\'node:path\');\nconst fs = require(\'node:fs\');\nconst { pathToFileURL } = require(\'node:url\');\nconst { registerDesktopUpdateHandlers } = require(\'./desktopUpdater.cjs\');\nconst { createWebviewBridge } = require(\'./webviewBridge.cjs\');\nconst { createAuthBridge } = require(\'./authBridge.cjs\');\nconst { createAuthStore } = require(\'./authStore.cjs\');\nconst { signInWithGoogle } = require(\'./googleAuth.cjs\');\nconst { resolveGoogleClientId } = require(\'./googleAuthConfig.cjs\');\n\nconst CUSTOM_SCHEME = \'yayra\';\nconst DIST_DIR = path.join(__dirname, \'..\', \'dist\');\nlet mainWindow;\nlet lastLoadError = null;\n\nprotocol.registerSchemesAsPrivileged([{ scheme: CUSTOM_SCHEME, privileges: { standard: true, secure: true, supportFetchAPI: true, corsEnabled: true } }]);\nif (process.env.YAYRA_SMOKE === \'1\' || process.env.IBROWSE_SMOKE === \'1\') {\n  app.commandLine.appendSwitch(\'headless\');\n  app.disableHardwareAcceleration();\n}\n\napp.whenReady().then(async () => {\n  protocol.handle(CUSTOM_SCHEME, async (request) => {\n    const url = new URL(request.url);\n    const pathname = safeAssetPath(url.pathname);\n    if (!pathname) return new Response(\'not found\', { status: 404 });\n    const file = path.join(DIST_DIR, pathname);\n    if (!file.startsWith(DIST_DIR) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) return new Response(\'not found\', { status: 404 });\n    const type = mimeType(file);\n    if (/\\.m?js$/.test(file) && !/javascript/.test(type)) return new Response(\'refused wrong MIME type\', { status: 415 });\n    return net.fetch(pathToFileURL(file).toString());\n  });\n  createWindow();\n});\n\napp.on(\'window-all-closed\', () => { if (process.platform !== \'darwin\') app.quit(); });\napp.on(\'activate\', () => { if (BrowserWindow.getAllWindows().length === 0) createWindow(); });\n\nfunction createWindow() {\n  mainWindow = new BrowserWindow({\n    width: 1200,\n    height: 800,\n    show: process.env.YAYRA_SMOKE !== \'1\' && process.env.IBROWSE_SMOKE !== \'1\',\n    webPreferences: {\n      preload: path.join(__dirname, \'preload.cjs\'),\n      contextIsolation: true,\n      nodeIntegration: false,\n      sandbox: true\n    }\n  });\n  registerDesktopUpdateHandlers({ getWindow: () => mainWindow });\n  // Native website-rendering engine bridge (replaces <iframe>-based rendering\n  // so real sites with X-Frame-Options/frame-ancestors - Google, GitHub,\n  // etc. - actually load). See electron/webviewBridge.cjs for the full\n  // architecture rationale.\n  const webviewBridge = createWebviewBridge({\n    WebContentsView,\n    ipcMain,\n    shell,\n    getMainWindow: () => mainWindow\n  });\n  mainWindow.on(\'closed\', () => webviewBridge.destroyAll());\n\n  // "Sign in with Google" for Yayra\'s own app-level identity. See\n  // electron/googleAuth.cjs + electron/authBridge.cjs for the full\n  // architecture rationale (RFC 8252 loopback + PKCE, system-browser-only).\n  const authStore = createAuthStore({\n    fs,\n    safeStorageImpl: safeStorage,\n    userDataDir: app.getPath(\'userData\')\n  });\n  createAuthBridge({\n    ipcMain,\n    shell,\n    getMainWindow: () => mainWindow,\n    authStore,\n    clientId: resolveGoogleClientId(),\n    signInImpl: signInWithGoogle\n  });\n\n  ipcMain.handle(\'yayra:get-launch-info\', () => ({\n    version: app.getVersion(),\n    updateState: \'diagnostics-ready\',\n    flags: process.argv.filter((arg) => arg.startsWith(\'--\')),\n    lastLoadError\n  }));\n  ipcMain.handle(\'ibrowse:get-launch-info\', () => ({\n    version: app.getVersion(),\n    updateState: \'diagnostics-ready\',\n    flags: process.argv.filter((arg) => arg.startsWith(\'--\')),\n    lastLoadError\n  }));\n  mainWindow.webContents.on(\'did-fail-load\', (_event, code, description, url) => {\n    lastLoadError = { code, description, url };\n    console.error(`[yayra] renderer load failed; retrying file fallback code=${code} url=${url}`);\n    if (!mainWindow.webContents.isDestroyed()) mainWindow.loadFile(path.join(DIST_DIR, \'index.html\'));\n  });\n  const isBadLoad = process.env.YAYRA_FORCE_BAD_LOAD === \'1\' || process.env.IBROWSE_FORCE_BAD_LOAD === \'1\';\n  const loadTarget = isBadLoad ? `${CUSTOM_SCHEME}://app/does-not-exist.html` : `${CUSTOM_SCHEME}://app/index.html`;\n  mainWindow.loadURL(loadTarget);\n  if (process.env.YAYRA_SMOKE === \'1\' || process.env.IBROWSE_SMOKE === \'1\') {\n    mainWindow.webContents.once(\'did-finish-load\', async () => {\n      const result = await mainWindow.webContents.executeJavaScript(\'({ title: document.title, hasRoot: Boolean(document.getElementById("app")), headerControl: Boolean(document.getElementById("update-button") || document.getElementById("top-header")) })\');\n      console.log(`[yayra-smoke] ${JSON.stringify(result)}`);\n      app.quit();\n    });\n    setTimeout(() => {\n      console.error(\'[yayra-smoke] timeout waiting for renderer paint\');\n      app.exit(1);\n    }, 15000).unref();\n  }\n}\n\nfunction safeAssetPath(rawPath) {\n  let decoded = rawPath || \'/\';\n  for (let i = 0; i < 3; i += 1) {\n    try {\n      const next = decodeURIComponent(decoded);\n      if (next === decoded) break;\n      decoded = next;\n    } catch {\n      break;\n    }\n  }\n  decoded = decoded.replace(/\\\\/g, \'/\');\n  if (decoded.includes(\'..\')) return null;\n  if (decoded === \'/\' || decoded === \'\') return \'index.html\';\n  return decoded.replace(/^\\/+/, \'\');\n}\n\nfunction mimeType(file) {\n  if (file.endsWith(\'.html\')) return \'text/html\';\n  if (file.endsWith(\'.js\') || file.endsWith(\'.mjs\')) return \'text/javascript\';\n  if (file.endsWith(\'.css\')) return \'text/css\';\n  if (file.endsWith(\'.json\')) return \'application/json\';\n  if (file.endsWith(\'.webmanifest\')) return \'application/manifest+json\';\n  if (file.endsWith(\'.png\')) return \'image/png\';\n  if (file.endsWith(\'.ico\')) return \'image/x-icon\';\n  return \'application/octet-stream\';\n}\n')
overwrite_file('electron/preload.cjs', 'const { contextBridge, ipcRenderer } = require(\'electron\');\n\nconst WEBVIEW_EVENT_CHANNEL = \'yayra:webview-event\';\nconst AUTH_EVENT_CHANNEL = \'yayra:auth-event\';\n\nconst api = {\n  getLaunchInfo: () => ipcRenderer.invoke(\'yayra:get-launch-info\'),\n  updates: {\n    check: () => ipcRenderer.invoke(\'yayra:updates-check\'),\n    install: () => ipcRenderer.invoke(\'yayra:updates-install\')\n  },\n  // Native website-rendering engine bridge. See electron/webviewBridge.cjs.\n  // Presence of `window.yayra.webview` is how the renderer\n  // (packages/shared-ui/src/components/BrowserShell.js) detects it is\n  // running inside Electron and should use the native WebContentsView engine\n  // instead of an <iframe> for rendering visited websites.\n  webview: {\n    ensure: (tabId, url, isPrivate = false) => ipcRenderer.invoke(\'yayra:webview-ensure\', { tabId, url, isPrivate }),\n    setBounds: (tabId, bounds) => ipcRenderer.invoke(\'yayra:webview-set-bounds\', { tabId, bounds }),\n    setVisible: (tabId, visible) => ipcRenderer.invoke(\'yayra:webview-set-visible\', { tabId, visible }),\n    goBack: (tabId) => ipcRenderer.invoke(\'yayra:webview-go-back\', { tabId }),\n    goForward: (tabId) => ipcRenderer.invoke(\'yayra:webview-go-forward\', { tabId }),\n    reload: (tabId) => ipcRenderer.invoke(\'yayra:webview-reload\', { tabId }),\n    stop: (tabId) => ipcRenderer.invoke(\'yayra:webview-stop\', { tabId }),\n    destroy: (tabId) => ipcRenderer.invoke(\'yayra:webview-destroy\', { tabId }),\n    onEvent: (callback) => {\n      const listener = (_event, payload) => callback(payload);\n      ipcRenderer.on(WEBVIEW_EVENT_CHANNEL, listener);\n      return () => ipcRenderer.removeListener(WEBVIEW_EVENT_CHANNEL, listener);\n    }\n  },\n  // "Sign in with Google" for Yayra\'s own app-level identity (not for\n  // browsing Google services logged in - Google forbids that for any\n  // embedded surface, see electron/webviewBridge.cjs). Presence of\n  // `window.yayra.auth` is how the renderer knows this desktop build\n  // supports real Google sign-in; it is absent on web/PWA/mobile builds\n  // until those platforms get their own implementation. See\n  // electron/googleAuth.cjs for the full flow.\n  auth: {\n    signIn: () => ipcRenderer.invoke(\'yayra:auth-sign-in\'),\n    signOut: () => ipcRenderer.invoke(\'yayra:auth-sign-out\'),\n    getSession: () => ipcRenderer.invoke(\'yayra:auth-get-session\'),\n    onEvent: (callback) => {\n      const listener = (_event, payload) => callback(payload);\n      ipcRenderer.on(AUTH_EVENT_CHANNEL, listener);\n      return () => ipcRenderer.removeListener(AUTH_EVENT_CHANNEL, listener);\n    }\n  }\n};\n\ncontextBridge.exposeInMainWorld(\'yayra\', api);\ncontextBridge.exposeInMainWorld(\'ibrowse\', api);\n')

